  "question": {
    "question_id": "gold-greffe-renale-everolimus",
    "sous_question": "Chez le receveur adulte de greffe rénale de novo, l'évérolimus associé à un inhibiteur de calcineurine est-il aussi efficace que l'acide mycophénolique associé au tacrolimus pour prévenir l'échec thérapeutique ?",
    "espece_cible": "human_in_vivo",
    "population": "adultes receveurs d'une greffe rénale de novo",
    "intervention": "évérolimus + tacrolimus ou ciclosporine contre acide mycophénolique + tacrolimus",
    "mesurande": {
      "nom": "échec thérapeutique (rejet aigu prouvé par biopsie, perte du greffon ou décès)",
      "unite": "incidence à 12 mois"
    },
    "exclusions": [],
    "requetes_initiales": {
      "pubmed": [
        "everolimus tacrolimus de novo kidney transplant"
      ],
      "arxiv": []
    }
  },
  "citation_verbatim": "Thus, everolimus with TAC or CsA showed comparable efficacy to MPA/TAC in de novo kidney transplant patients.",
  "source_id": "pmid:31027892",
  "drapeaux": {
    "is_future_or_protocol": false,
